insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 7, 'E Jesua, Bani, e Serebias, Jamim, Acube, Sabetai, Hodias, Maaseias, Quelita, Azarias, Jozabade, Hanã, Pelaías, e os levitas, ensinavam ao povo a lei; e o povo estava em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 8, 'E leram no livro da lei de Deus o declarando, e explicando o sentido, para que pudessem entender o que era lido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 9, 'E Neemias (que era o governador), e o sacerdote Esdras, escriba, e os levitas que ensinavam ao povo, disseram a todo o povo: Este dia é consagrado ao SENHOR nosso Deus; não vos entristeçais, nem choreis. Porque todo o povo chorava enquanto ouvia as palavras da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 10, 'E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 11, 'E os levitas faziam todo o povo ficar calado, dizendo: Calai-vos, que é dia santo, e não vos entristeçais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 12, 'Então todo o povo foi embora para comer, beber, enviar porções, e celebrar alegremente, porque entenderam as palavras que lhes haviam ensinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 13, 'E no dia seguinte se juntaram os líderes das famílias de todo o povo, os sacerdotes, os levitas, o e o escriba Esdras, para estudarem as palavras da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 14, 'E acharam escrito na lei que o SENHOR havia mandado por meio de Moisés, que os filhos de Israel habitassem em tendas na solenidade do mês sétimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 15, 'Por isso eles anunciaram publicamente, e proclamaram por todas as suas cidades e por Jerusalém, dizendo: Saí ao monte, trazei ramos de oliveiras, e ramos de oliveiras silvestres, e ramos de murta, ramos de palmeiras, e ramos de toda árvore espessa, para fazer tendas como está escrito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 16, 'Saiu, pois, povo, e os trouxeram, e fizeram para si tendas, cada um sobre seu terraço, em seus pátios, nos pátios da casa de Deus, na praça da porta das Águas, e na praça da porta de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 17, 'E toda a congregação dos que voltaram do cativeiro fizeram tendas, e em tendas habitaram; porque os filhos de Israel, desde os dias de Josué filho de Num até aquele dia, não haviam feito assim. E houve alegria muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 18, 'E a cada dia Esdras leu no livro da lei de Deus, desde o primeiro dia até o último; e celebraram a solenidade durante sete dias, e ao oitavo dia houve uma assembleia solene, conforme a ordenança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 1, 'No dia vinte e quatro do mesmo mês, os filhos de Israel se reuniram em jejum, com sacos, e com terra sobre si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 2, 'E a descendência de Israel já havia se separado de todos os estrangeiros; então puseram-se de pé, confessaram seus pecados, e as iniquidades de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 3, 'Pois, levantados de pé em seu lugar, leram no livro da lei de SENHOR seu Deus uma quarta parte do dia, e em [outra] quarta parte confessaram e adoraram ao SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 4, 'E Jesua, Bani, Cadmiel, Serebias, Buni, Sebanias, Bani e Quenai, se puseram de pé na escadaria dos Levitas, e clamaram em alta voz ao SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 5, 'E os levitas Jesua, Cadmiel, Bani, Hasbaneias, Serebias, Hodias, Sebanias e Petaías, disseram: Levantai-vos, bendizei ao SENHOR vosso Deus para todo o sempre: Bendito o teu glorioso nome, que está exaltado sobre toda bênção e louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 6, 'Tu és o único, SENHOR! Tu fizeste o céu, o céu dos céus, e toda o seu exército; a terra e tudo quanto nela há; os mares e tudo quanto neles há; e tu vivificas a todos; os exércitos dos céus te adoram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 7, 'Tu és, SENHOR, o Deus que escolheste a Abrão, e o tiraste de Ur dos caldeus, e puseste nele o nome Abraão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 8, 'E achaste o coração dele fiel diante de ti, e fizeste com ele o pacto para lhe dar a terra dos cananeus, dos heteus, dos amorreus, dos perizeus, dos jebuseus, e dos girgaseus, para a dares à sua descendência; e cumpriste as tuas palavras, porque és justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 9, 'E olhaste para a aflição de nossos pais no Egito, e ouviste o clamor deles junto ao mar Vermelho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 10, 'E deste sinais e maravilhas a Faraó, e a todos os seus servos, e a todo o povo de sua terra; porque sabias que os tratariam com soberba; e assim fizeste famoso o teu nome, tal como o é hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 11, 'E dividiste o mar diante deles, e passaram por meio do mar a seco; e lançaste a seus perseguidores nas profundezas, como uma pedra em águas violentas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 12, 'E com coluna de nuvem os guiaste de dia, e com coluna de fogo de noite, para os iluminares no caminho por onde haviam de ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 13, 'E sobre o monte de Sinai desceste, e falaste com eles desde o céu; e deste-lhes regras justas, leis verdadeiras, e estatutos e mandamentos bons.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 14, 'E ensinaste a eles teu santo sábado; e lhes mandaste preceitos e estatutos, por meio de teu servo Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 15, 'E deste-lhes pão do céu em sua fome, e em sua sede lhes tiraste águas da pedra; e disseste a eles que entrassem para tomar posse da terra, pela qual juraste com mão erguida, que a darias a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 16, 'Porém eles, nossos pais, agiram com soberba; endureceram sua cerviz, e não deram ouvidos a teus mandamentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 17, 'E recusaram [te] ouvir, e não se lembraram de tuas maravilhas que havias feito com eles; ao invés disso, endureceram sua cerviz, e em sua rebelião levantaram um líder para voltarem à sua escravidão. Porém tu, que és Deus que perdoas, clemente e misericordioso, tardio para se irar, e grande em bondade, não os desamparaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 18, 'Até quando fizeram para si bezerro de fundição, e disseram: Este é teu Deus que te tirou do Egito; e cometeram grandes blasfêmias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 19, 'Tu, contudo, pela tua grande misericórdia não os abandonaste no deserto; a coluna de nuvem nunca se afastou deles de dia, para os guiar pelo caminho, nem a coluna de fogo de noite, para os iluminar no caminho pelo qual haviam de ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 20, 'E deste o teu bom Espírito para os ensinar, e não tiraste o teu maná de suas bocas, e lhes deste água em sua sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 21, 'Assim os sustentaste por quarenta anos no deserto; de nenhuma coisa tiveram falta; suas roupas não se envelheceram, nem seus pés se incharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 22, 'Também lhes deste reinos e povos, e os repartistes por cantos; assim tomaram posse da terra de Siom, a terra do rei de Hesbom, e a terra de Ogue, rei de Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 23, 'E multiplicaste seus filhos como as estrelas do céu, e os trouxeste à terra, da qual tinhas dito a seus pais, que entrariam para tomarem posse dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 24, 'Assim os filhos vieram, e tomaram posse daquela terra; e abateste diante deles aos moradores do território, os cananeus, e os entregaste em suas mãos, como também a seus reis, e aos povos do território, para que fizessem deles à sua vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 25, 'E tomaram cidades fortificadas e terra fértil, e tomaram posse de casas cheias de toda fartura, cisternas cavadas, vinhas e olivais, e muitas árvores frutíferas; e comeram, se fartaram, engordaram, e se deleitaram pela tua grande bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 26, 'Porém eles foram desobedientes, e se rebelaram contra ti; desprezaram tua lei, e mataram teus profetas que lhes alertavam para que convertessem a ti; assim fizeram grandes abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 27, 'Por isso tu os entregaste nas mãos de seus inimigos, os quais os afligiram; e no tempo de sua angústia clamaram a ti, e tu desde os céus os ouviste; e segundo tua grande misericórdia tu lhes davas libertadores, que os salvaram da mão de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 28, 'Mas assim que tinham repouso, voltavam a fazer o mal diante de ti; e tu os abandonavas nas mãos de seus inimigos, para que os dominassem. E eles se convertiam, e clamavam a ti, e tu os ouvias desde os céus; e segundo tua misericórdia muitas vezes os livraste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 29, 'E os alertaste, para os fazer voltar à tua lei; porém eles agiram com soberba, e não deram ouvidos teus mandamentos; ao invés disso, pecaram contra teus juízos, os quais quem praticar, por causa deles viverá; e deram as costas, endureceram sua cerviz, e não deram ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 30, 'Porém os suportaste por muitos anos, e os alertaste com teu Espírito por meio de teus profetas, mas não deram ouvidos; por isso tu os entregaste nas mãos dos povos das terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 31, 'Mas por tua grande misericórdia não os destruíste por completo, nem os desamparaste; porque tu és Deus clemente e misericordioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 32, 'Agora pois, Deus nosso, Deus grande, poderoso e temível, que guardas o pacto e a bondade, não consideres pouco toda a opressão que alcançou a nós, nossos reis, nossos príncipes, nossos sacerdotes, nossos profetas, nossos pais, e todo o teu povo, desde os dias dos reis da Assíria até o dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 33, 'Tu, porém, és justo em tudo quanto veio sobre nós; porque agiste fielmente, mas nós agimos perversamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 34, 'E nossos reis, nossos príncipes, nossos sacerdotes, e nossos pais, não praticaram tua lei, nem deram ouvidos a teus mandamentos e teus testemunhos, com que os alertavas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 35, 'Porque eles, mesmo em seu reino, nos muitos bens que lhes deste, e na terra espaçosa e fértil que entregaste a deles, não te serviram, nem se converteram de suas más obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 36, 'Eis que hoje somos servos, na terra que havias dado a nossos pais para que comessem seus fruto e o seu bem, eis que nela somos servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 37, 'E sua grande renda é para os reis que puseste sobre nós por nossos pecados; e eles à sua vontade dominam sobre nossos corpos e sobre nossos animais, e estamos em grande angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 9, 38, 'A por causa de tudo isso nós fazemos [um pacto] fiel, e o escrevemos, e nossos príncipes, nossos Levitas, e nossos sacerdotes o selaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 1, 'E os que selaram foram: Neemias o governador, filho de Hacalias, e Zedequias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 2, 'Seraías, Azarias, Jeremias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 3, 'Pasur, Amarias, Malquias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 4, 'Hatus, Sebanias, Maluque,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 5, 'Harim, Meremote, Obadias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 6, 'Daniel, Ginetom, Baruque,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 7, 'Mesulão, Abias, Miamim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 8, 'Maazias, Bilgai, Semaías: estes eram o sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 9, 'E os Levitas: Jesua filho de Azanias, Binui dos filhos de Henadade, Cadmiel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 10, 'E seus irmãos Sebanias, Hodias, Quelita, Pelaías, Hanã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 11, 'Mica, Reobe, Hasabias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 12, 'Zacur, Serebias, Sebanias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 13, 'Hodias, Bani, e Beninu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 14, 'Os líderes do povo: Parós, Paate-Moabe, Elão, Zatu, Bani,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 15, 'Bani, Azgade, Bebai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 16, 'Adonias, Bigvai, Adim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 17, 'Ater, Ezequias, Azur,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 18, 'Hodias, Hasum, Besai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 19, 'Harife, Anatote, Nebai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 20, 'Magpias, Mesulão, Hezir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 21, 'Mesezabel, Zadoque, Jadua,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 22, 'Pelatias, Hanã, Anaías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 23, 'Oseias, Hananias, Hassube,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 24, 'Haoés, Pílea, Sobeque,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 25, 'Reum, Hasabna, Maaseias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 26, 'Aías, Hanã, Anã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 27, 'Maluque, Harim, e Baaná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 28, 'E o resto do povo, os sacerdotes, os levitas, os porteiros, os cantores, os servos do templo, e todos os que se haviam se separado dos povos das terras para a lei de Deus, suas mulheres, seus filhos e suas filhas, e todo o que tinha compreensão [e] entendimento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 29, 'Firmemente se juntaram a seus irmãos, os mais nobres dentre eles, e se comprometeram em um juramento sujeito a maldição, que andariam na lei de Deus, que foi dada por meio de Moisés, servo de Deus, e que guardariam e cumpririam todos os mandamentos do SENHOR nosso Senhor, e seus juízos e seus estatutos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 30, 'E que não daríamos nossas filhas aos povos da região, nem tomaríamos suas filhas para nossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 31, 'E que, se os povos da região trouxessem para vender mercadorias e comida no dia de sábado, nada tomaríamos deles no sábado, nem em dia santo; e deixaríamos livre o sétimo ano, inclusive toda e qualquer cobrança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 32, 'Também pusemos preceitos sobre nós, impondo-nos a cada ano [dar] a terça parte de um siclo, para a obra da casa de nosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 33, 'Para os pães da proposição, para a oferta contínua de alimentos, e para o holocausto contínuo, dos sábados, das novas luas, e das festas solenes, e para as coisas sagradas, e para os sacrifícios pelo pecado para reconciliar a Israel, e [para] toda a obra da casa de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 34, 'Também lançamos as sortes entre os sacerdotes, os levitas, e o povo, acerca da oferta da lenha, que havia de se trazer à casa de nosso Deus, segundo as casas de nossos pais, em tempos determinados, a cada ano, para queimar sobre o altar do SENHOR nosso Deus, como está escrito na lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 35, 'E que a cada ano traríamos as primícias de nossa terra, e todos os primeiros frutos de toda árvore, para a casa de SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 36, 'E também os primogênitos de nossos filhos e de nossas animais, como está escrito na lei; e que traríamos os primogênitos de nossas vacas e de nossas ovelhas à casa de nosso Deus, aos sacerdotes que ministram na casa de nosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 37, 'E que traríamos as primícias de nossas massas, e nossas ofertas alçadas, e do fruto de toda árvore, do suco de uva e do azeite, aos sacerdotes, às câmaras da casa de nosso Deus, e os dízimos de nossa terra aos levitas; e que os levitas receberiam os dízimos em todas as cidades onde trabalhamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 38, 'E que um sacerdote, filho de Arão, estaria com os levitas, quando os levitas recebessem os dízimos; e que os levitas trariam o dízimo dos dízimos à casa de nosso Deus, às câmaras da casa do tesouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 10, 39, 'Porque para aquelas câmaras os filhos de Israel, e os filhos de Levi, devem trazer a oferta de grão, de suco de uva, e de azeite; e ali estarão os vasos do santuário, como também os sacerdotes que ministram, os porteiros, e os cantores; e assim não abandonaríamos a casa de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 1, 'E os líderes do povo habitaram em Jerusalém; porém os demais do povo lançaram sortes para trazerem um de dez para habitar na santa cidade de Jerusalém, e as nove partes nas outras cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 2, 'E o povo abençoou a todos os homens que voluntariamente se ofereceram para habitarem em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 3, 'E estes são os chefes da província que habitaram em Jerusalém (porém os israelitas, os sacerdotes e os levitas, os servos do templo, e os filhos dos servos de Salomão, nas cidades de Judá, habitaram cada um em sua possessão, em suas cidades).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 4, 'Habitaram, pois, em Jerusalém , [alguns] dos filhos de Judá, e dos filhos de Benjamim. Dos filhos de Judá: Ataías, filho de Uzias, filho de Zacarias, filho de Amarias, filho de Sefatias, filho de Maalaleel, dos filhos de Perez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 5, 'E Maaseias filho de Baruque, filho de Col-Hozé, filho de Hazaías, filho de Adaías, filho de Joiaribe, filho de Zacarias, filho de Siloni.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 6, 'Todos os filhos de Perez que habitaram em Jerusalém foram quatrocentos setenta e oito homens valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 7, 'E estes são os filhos de Benjamim: Salu filho de Mesulão, filho de Joede, filho de Pedaías, filho de Colaías, filho de Maaseias, filho de Itiel, filho de Jesaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 8, 'E após ele, Gabai, Salai, novecentos e vinte e oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 9, 'E Joel, filho de Zicri, era o supervisor deles; e Judá filho de Senua, o segundo sobre a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 10, 'Dos sacerdotes: Jedaías filho de Joiaribe, Jaquim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 11, 'Seraías filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, governador da casa de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 12, 'E seus irmãos, que faziam a obra da casa, oitocentos vinte e dois; e Adaías filho de Jeroão, filho de Pelalias, filho de Anzi, filho de Zacarias, filho de Pasur, filho de Malquias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 13, 'E seus irmãos, chefes de famílias, duzentos e quarenta e dois; e Amassai filho de Azareel, filho de Azai, filho de Mesilemote, filho de Imer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 14, 'E seus irmãos, homens valentes, cento e vinte e oito; e o supervisor sobre eles era Zabdiel, filho de Gedolim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 15, 'E dos Levitas: Semaías filho de Hassube, filho de Azricão, filho de Hasabias, filho de Buni;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 16, 'Sabetai e Jozabade, dos chefes dos Levitas, supervisores da obra de fora da casa de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 17, 'E Matanias filho de Mica, filho de Zabdi, filho de Asafe, o chefe, o que começava a ação de graças na oração; e Baquebuquias o segundo de entre seus irmãos; e Abda filho de Samua, filho de Galal, filho de Jedutum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 18, 'Todos os levitas na santa cidade foram duzentos e oitenta e quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 19, 'E os porteiros, Acube, Talmom, com seus irmãos, os guardas das portas: cento e setenta e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 20, 'E o demais dos israelitas, dos sacerdotes, dos levitas, estevem em todas as cidades de Judá, cada um em sua propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 21, 'E os servos do templo habitavam em Ofel; e Zia e Gispa governavam sobre os servos do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 22, 'E o supervisor dos levitas em Jerusalém foi Uzi, filho de Bani, filho de Hasabias, filho de Matanias, filho de Mica; dos filhos de Asafe estavam os cantores diante da obra da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 23, 'Porque tinha mandamento do rei acerca deles, e determinação acerca dos cantores para cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 24, 'E Petaías filho de Mesezabel, dos filhos de Zerá, filho de Judá, estava à mão do rei em todo negócio do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 25, 'E quanto às aldeias em suas terras, alguns dos filhos de Judá habitaram em Quiriate-Arba, nas suas aldeias circunvizinhas, em Dibom e suas aldeias circunvizinhas, e em Jecabzeel e suas aldeias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 26, 'E em Jesua, Molada, Bete-Pelete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 27, 'Hazar-Sual, Berseba, e em suas aldeias circunvizinhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 28, 'E em Ziclague, e em Meconá, e em suas aldeias circunvizinhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 29, 'E em En-Rimom, Zorá Jarmute;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 30, 'Zanoa, Adulão, e em suas aldeias; em Laquis e suas terras; Azeca e suas aldeias circunvizinhas. E habitaram desde Berseba até o vale de Hinom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 31, 'E os filhos de Benjamim desde Geba [habitaram] em Micmás, Aia, e Betel e suas aldeias circunvizinhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 32, 'Em Anatote, Nobe, Ananias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 33, 'Hazor, Ramá, Gitaim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 34, 'Hadide, Zeboim, Nebalate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 35, 'Lode, e Ono, no vale dos artífices.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 11, 36, 'E [alguns] dos Levitas, nos repartições de Judá e de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 1, 'Estes são os sacerdotes e Levitas que subiram com Zorobabel filho de Sealtiel, e com Jesua: Seraías, Jeremias, Esdras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 2, 'Amarias, Maluque, Hatus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 3, 'Secanias, Reum, Meremote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 4, 'Ido, Ginetoi, Abias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 5, 'Miamim, Maadias, Bilga,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 6, 'Semaías, e Joiaribe, Jedaías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 7, 'Salu, Amoque, Hilquias, Jedaías. Estes eram os chefes dos sacerdotes e seus irmãos nos dias de Jesua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 8, 'E os levitas foram:Jesua, Binui, Cadmiel, Serebias, Judá, e Matanias: este e seus irmãos eram responsáveis pelas ações de graças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 9, 'E Bacbuquias e Uni, seus irmãos, em frente deles em suas responsabilidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 10, 'E Jesua gerou a Joiaquim, e Joiaquim gerou a Eliasibe e Eliasibe gerou a Joiada,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 11, 'E Joiada gerou a Jônatas, e Jônatas gerou a Jadua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 12, 'E nos dias de Joiaquim os sacerdotes chefes das famílias foram: de Seraías, Meraías; de Jeremias, Hananias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 13, 'De Esdras, Mesulão; de Amarias, Joanã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 14, 'De Maluqui, Jônatas; de Sebanias, José;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 15, 'De Harim, Adna; de Meraiote, Helcai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 16, 'De Ido, Zacarias; de Ginetom, Mesulão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 17, 'De Abias, Zicri; de Miniamim, [e] de Moadias, Piltai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 18, 'De Bilga, Samua; de Semaías, Jônatas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 19, 'De Joiaribe, Matenai; de Jedaías, Uzi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 20, 'De Salai, Calai; de Amoque, Éber;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 21, 'De Hilquias, Hasabias; de Jedaías, Natanael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 22, 'Os Levitas nos dias de Eliasibe, de Joiada, e de Joanã e Jadua, foram escritos por chefes de famílias; como também os sacerdotes, até o reinado de Dario o persa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 23, 'Os filhos de Levi, chefes de famílias, foram escritos no livro das crônicas até os dias de Joanã, filho de Eliasibe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 24, 'E os chefes dos Levitas foram:Hasabias, Serebias, e Jesua filho de Cadmiel, e seus irmãos em frente deles, para louvarem [e] darem graças, conforme o mandamento de Davi, homem de Deus, cada um com sua responsabilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 25, 'Matanias, e Bacbuquias, Obadias, Mesulão, Talmom, Acube, eram porteiros que faziam guarda às entradas das portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 26, 'Estes foram nos dias de Joiaquim, filho de Jesua, filho de Jozadaque, como também nos dias do governador Neemias, e do sacerdote Esdras, o escriba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 27, 'E na dedicação dos muros de Jerusalém buscaram aos Levitas de todos os lugares, para os trazerem a Jerusalém, a fim de fazerem a dedicação com alegrias, com ações de graças, e com cânticos, com címbalos, liras e harpas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 28, 'E assim ajuntaram os filhos dos cantores, tanto da planície ao redor de Jerusalém como das aldeias de Netofati;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 29, 'Como também da casa de Gilgal, e dos campos de Geba, e de Azmavete; porque os cantores haviam edificado para si aldeias ao redor de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 30, 'E os sacerdotes e os levitas se purificaram, e depois purificaram ao povo, às portas, e ao muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 31, 'Então eu fiz subir aos príncipes de Judá sobre o muro, e ordenei dois coros grandes que foram em procissão: um à direita sobre o muro em direção à porta do Esterco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 32, 'E após eles ia Hosaías, e a metade dos príncipes de Judá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 33, 'E Azarias, Esdras, Mesulão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 34, 'Judá, Benjamim, Semaías, e Jeremias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 35, 'E dos filhos dos sacerdotes com trombetas, Zacarias filho de Jônatas, filho de Semaías, filho de Matanias, filho de Micaías, filho de Zacur, filho de Asafe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 36, 'E seus irmãos Semaías, e Azareel, Milalai, Gilalai, Maai, Natanael, Judá e Hanani, com os instrumentos musicais de Davi, homem de Deus; e o escriba Esdras [ia] diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 37, '[Indo] assim para a porta da Fonte, e em frente deles, subiram pelas escadarias da cidade de Davi, pela subida do muro, desde acima da casa de Davi até a porta das Águas ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 38, 'E o segundo coro ia do lado oposto, e eu atrás dele; e a metade do povo [ia] sobre o muro, desde a torre dos Fornos até a muralha larga;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 39, 'E desde a porta de Efraim até a porta Velha, e à porta do Peixe, e a torre de Hananeel, e a torre dos Cem, até a porta das Ovelhas; e pararam na porta da Prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 40, 'Então ambos os coros pararam na casa de Deus; como também eu, e a metade dos oficiais comigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 41, 'E os sacerdotes, Eliaquim, Maaseias, Miniamim, Micaías, Elioenai, Zacarias, e Hananias, com trombetas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 42, 'Como também Maaseias, Semaías, Eleazar, e Uzi, Joanã, Malquias, Elão, e Ezer. E os cantores cantavam alto, juntamente com o supervisor Jezraías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 43, 'E sacrificaram naquele dia grandes sacrifícios, e alegraram-se; porque Deus os tinha alegrado muito; alegraram-se também a mulheres e as crianças; e o júbilo de Jerusalém foi ouvido até de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 44, 'Também naquele dia foram postos homens sobre as câmaras para os tesouros, as ofertas alçadas, as primícias, e os dízimos, para juntarem nelas, dos campos das cidades, as porções da lei para os sacerdotes e os levitas; porque Judá estava alegre por causa dos sacerdotes e dos levitas que estavam servindo ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 45, 'E faziam a guarda de seu Deus, e a guarda da purificação, como também os cantores e os porteiros, conforme o mandamento de Davi e de seu filho Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 46, 'Porque nos dias de Davi e de Asafe, desde a antiguidade, havia chefes dos cantores, e cânticos de louvor e de ações de graças a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 12, 47, 'E todo Israel nos dias de Zorobabel, e nos dias de Neemias, dava as porções dos cantores e dos porteiros, cada uma em seu dia; e consagravam [porções] aos levitas, e os levitas [as] consagravam aos filhos de Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 1, 'Naquele dia se leu no livro de Moisés perante os ouvidos do povo, e foi achado nele escrito que os amonitas e os moabitas eternamente não podiam entrar na congregação de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 2, 'Porque não saíram ao encontro dos filhos de Israel com pão e água; em vez disso, contrataram a Balaão contra eles, para os amaldiçoar; ainda que nosso Deus tornou a maldição em bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 3, 'Sucedeu, pois, que, quando eles ouviram esta lei, separaram de Israel toda mistura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 4, 'E antes disto, Eliasibe, o sacerdote, sendo superintendente da câmara da casa de nosso Deus, tinha se aparentado com Tobias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 5, 'E tinha lhe preparado uma câmara grande, na qual antes se guardavam as ofertas de alimentos, o incenso, os vasos, os dízimos de grão, de vinho e de azeite, que estava ordenado [dar] aos levitas, aos cantores, e aos porteiros; como também a oferta alçada para os sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 6, 'Porém enquanto tudo isto [acontecia] ,eu não estava em Jerusalém; porque no ano trinta e dois de Artaxerxes rei da Babilônia, eu vim ao rei; mas ao fim de [alguns] dias obtive permissão para me ausentar do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 7, 'E vim a Jerusalém, e entendi o mal que Eliasibe tinha feito por Tobias, preparando-lhe uma câmara nos pátios da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 8, 'E isso me desagradou muito; por isso lancei todas as coisas da casa de Tobias para fora da câmara;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 9, 'E mandei purificar as câmaras, e trouxe de volta os utensílios da casa de Deus, com as ofertas de alimento, e o incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 10, 'Também entendi que as porções dos Levitas não estavam sendo dadas [a eles] ; e que os levitas e cantores que faziam o serviço haviam fugido cada um para seu campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 11, 'Então repreendi aos oficiais, e disse: Por que a casa de Deus está abandonada? Porém eu os juntei, e os restaurei em seu posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 12, 'Então todo Judá trouxe o dízimo do grão, do suco de uva e do azeite, aos depósitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 13, 'E pus por tesoureiros sobre os depósitos ao sacerdote Selemias e ao escriba Zadoque, e dos Levitas, a Pedaías; e próximo a eles Hanã filho de Zacur, filho de Matanias; pois eram considerados fiéis, e [assim] foram encarregados de distribuírem a seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 14, 'Por isto, meu Deus, lembra-te de mim, ó Deus, e não risques minhas bondades que eu fiz na casa de meu Deus, e em seus serviços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 15, 'Naqueles dias vi em Judá [alguns] que pisavam nas presnas de uvas no sábado, e que traziam feixes, e carregavam asnos, como também vinho, uvas, figos, e todo tipo de carga, que traziam a Jerusalém no dia de sábado; e os adverti quanto ao dia em que vendiam alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 16, 'Também tírios estavam nela que traziam peixe e toda mercadoria, e vendiam no sábado aos filhos de Judá, e em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 17, 'Assim repreendi aos nobres de Judá, e disse-lhes: Que mal é este que fazeis, profanando o dia de sábado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 18, 'Por acaso não fizeram assim vossos pais, e nosso Deus trouxe todo este mal sobre nós e sobre esta cidade? Porém vós acrescentais ainda mais ira sobre Israel profanando o sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 19, 'Sucedeu pois, que quando ia escurecendo às portas de Jerusalém antes do sábado, disse que eu mandei que se fechassem as portas, e mandei que não as abrissem até depois do sábado; e pus às portas alguns de meus servos, para que carga nenhuma entrasse no dia de sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 20, 'Assim os comerciantes e vendedores de toda mercadoria passaram a noite fora de Jerusalém uma ou duas vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 21, 'Por isso eu lhes adverti, dizendo: Por que vos passais a noite diante do muro? Se o fizerdes outra vez, agirei com violência contra vós. Desde então não vieram no sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 22, 'Também disse aos levitas que se purificassem, e viessem a guardar as portas, para santificar o dia de sábado. Nisto também, meu Deus, lembra-te de mim, e perdoa-me segundo a grandeza de tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 23, 'Vi também naqueles dias judeus que tinham se casado com mulheres de asdoditas, amonitas, e moabitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 24, 'E seus filhos a metade falavam asdodita, e não sabiam falar judaico, mas sim a língua de outros povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 25, 'Por isso eu os repreendi, e os amaldiçoei, e espanquei [alguns] deles, e arranquei-lhes os cabelos, e os fiz jurar por Deus, dizendo: Não dareis vossas filhas a seus filhos, e não tomareis de suas filhas, nem para vossos filhos, nem para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 26, 'Por acaso não pecou nisto Salomão, rei de Israel? Ainda que entre muitas nações não houve rei semelhante a ele, que era amado pelo seu Deus, e Deus o tinha posto por rei sobre todo Israel, [contudo] as mulheres estrangeiras o fizeram pecar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 27, 'E aceitaríamos ouvir de vós, para fazerdes todo este mal tão grande de transgredir contra nosso Deus, casando-se com mulheres estrangeiras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 28, 'E um dos filhos de Joiada, filho de Eliasibe o sumo sacerdote era genro de Sambalate o horonita; por isso eu o afugentei de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 29, 'Lembra-te deles, meu Deus, pois contaminam o sacerdócio, como também o pacto do sacerdócio e dos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 30, 'Assim eu os limpei de todo estrangeiro, e ordenei as responsabilidades dos sacerdotes e dos levitas, cada um em sua obra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 13, 31, 'Como também para as ofertas de lenha em tempos determinados, e para as primícias. Lembra-te de mim, meu Deus, para o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 1, 'E aconteceu nos dias de Assuero (o Assuero que reinou desde a Índia até Cuxe sobre cento e vinte e sete províncias),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 2, 'Que naqueles dias, quando o rei Assuero se sentou sobre o trono de seu reino, na fortaleza de Susã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 3, 'No terceiro ano de seu reinado, ele fez um banquete a todos seus príncipes e a seus servos, tendo diante dele o exército de Pérsia e da Média, os maiorais e os governadores das províncias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 4, 'Para mostrar as riquezas da glória de seu reino, e o esplendor de sua majestosa grandeza, por muitos dias: cento e oitenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 5, 'E acabados aqueles dias, o rei fez um banquete a todo o povo que se achava na fortaleza de Susã, desde o maior até o menor, durante sete dias, no pátio do jardim do palácio real.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 6, '[As cortinas eram] de linho branco e azul celeste, amarradas com cordões de linho fino e púrpura, argolas de prata e colunas de mármore; os leitos eram de ouro e de prata, sobre um piso de pórfiro , mármore, madrepérola e pedras preciosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 7, 'E dava-se de beber em taças de ouro, e as taças eram diferentes umas das outras; e havia muito vinho real, conforme a generosidade do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 8, 'E de acordo com a lei, a bebida era sem restrições; porque assim o rei tinha mandado a todos os oficiais de sua casa; que fizessem conforme a vontade de cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 9, 'Também a rainha Vasti fez banquete para as mulheres, na casa real do rei Assuero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 10, 'No sétimo dia, quando o coração do rei estava alegre do vinho, mandou a Meumã, Bizta, Harbona, Bigtá, Abagta, Zetar, e Carcas, sete eunucos que serviam diante do rei Assuero,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 11, 'Que trouxessem à rainha Vasti com a coroa real diante do rei, para mostrar aos povos e aos príncipes sua beleza; pois ela tinha linda aparência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 12, 'Porém a rainha Vasti recusou vir à ordem do rei por meio dos eunucos; por isso o rei se enfureceu muito, e sua ira se acendeu nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 13, 'Então o rei perguntou aos sábios que entendiam dos tempos (porque assim era o costume do rei para com todos os que sabiam a lei e o direito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 14, 'E os mais próximos dele eram Carsena, Setar, Adamata, Társis, Meres, Marsena, e Memucã, sete príncipes da Pérsia e da Média, que viam o rosto do rei, e se sentavam nas [posições] principais do reino)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 15, 'O que se devia fazer segundo a lei com a rainha Vasti, por não ter cumprido a ordem do rei Assuero por meio dos eunucos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 16, 'Então Memucã disse na presença do rei e dos príncipes: A rainha Vasti pecou não somente contra o rei, mas também contra todos os príncipes, e contra todos os povos que há em todas as províncias do rei Assuero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 17, 'Pois o que a rainha fez será notícia a todas as mulheres, de modo que desprezarão seus maridos em seus olhos, quando lhes for dito: O rei Assuero mandou trazer diante de si à rainha Vasti, porém ela não veio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 18, 'Então neste dia as princesas da Pérsia e da Média dirão [o mesmo] a todos os príncipes do rei, quando ouvirem o que a rainha fez; e [assim] haverá muito desprezo e indignação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 19, 'Se for do agrado do rei, seja feito de sua parte um mandamento real, e escreva-se nas leis da Pérsia e da Média, e que não se possa revogar: que Vasti nunca mais venha diante do rei Assuero; e o reino dela seja dado a outra que seja melhor que ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 20, 'E quando o mandamento que o rei ordenar for ouvido em todo o seu reino (ainda que seja grande), todas as mulheres darão honra a seus maridos, desde o maior até o menor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 21, 'E esta palavra foi do agrado dos olhos do rei e dos príncipes, e o rei fez conforme o que Memucã havia dito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 1, 22, 'Então enviou cartas a todas a províncias do rei, a cada província segundo sua escrita, e a cada povo segundo sua língua, que todo homem fosse senhor em sua casa, e falasse isto conforme a língua de cada povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 1, 'Passadas estas coisas, e tendo já sido apaziguado o furor do rei Assuero, ele se lembrou de Vasti, e do que ela havia feito, e do que havia sido sentenciado contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 2, 'Então os servos do rei, que lhe serviam, disseram: Busquem-se ao rei moças virgens de boa aparência;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 3, 'E o rei ponha comissários em todas as províncias de seu reino, para que juntem todas as moças virgens de boa aparência na fortaleza de Susã, na casa das mulheres, ao cuidado de Hegai, eunuco do rei, vigilante das mulheres; e sejam lhes dado seus enfeites;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 4, 'E a moça que agradar aos olhos do rei, reine em lugar de Vasti.E isto foi do agrado dos olhos do rei, e ele assim fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 5, 'Havia um homem judeu na fortaleza de Susã, cujo nome era Mardoqueu, filho de Jair, filho de Simei, filho de Quis, um homem da [linhagem] de Benjamim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 6, 'O qual tinha sido levado de Jerusalém com os cativos que foram levados com Jeconias rei de Judá, a quem Nabucodonosor, rei da Babilônia, havia levado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 7, 'E ele tinha criado a Hadassa, que é Ester, filha de seu tio, porque não tinha pai nem mãe; e ela tinha bela forma, e era linda de aparência; e como seu pai e sua mãe tinham morrido, Mardoqueu a havia tomado como sua filha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 8, 'Sucedeu pois, que quando se divulgou o mandamento do rei e seu lei, e sendo reunidas muitas moças na fortaleza de Susã, ao cuidado de Hegai, também levaram Ester para casa do rei, ao cuidado de Hegai, vigilante das mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 9, 'E a moça foi do agrado de seus olhos, e alcançou favor diante dele; por isso ele se apressou em [lhe dar] seus enfeites e suas porções de alimento, dando-lhe também sete moças escolhidas da casa do rei; e ele a passou com suas moças ao melhor [lugar] da casa das mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 10, 'Ester, porém, não declarou seu povo nem sua parentela; porque Mardoqueu tinha lhe mandado que não declarasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 11, 'E todo dia Mardoqueu passeava diante do pátio da casa das mulheres, para saber como Ester estava, e que estava acontecendo com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 12, 'E quando chegava a vez de cada uma das moças para vir ao rei Assuero, ao fim de haver estado doze meses, conforme à lei acerca das mulheres (porque assim se cumpriam os dias de seus enfeites, isto é, seis meses com óleo de mirra, e seis meses com especiarias, e [outros] enfeites de mulheres),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 13, 'Então assim a moça vinha ao rei; tudo quanto ela pedia se lhe dava, para vir com isso da casa das mulheres até a casa do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 14, 'Ela vinha à tarde, e pela manhã voltava à segunda casa das mulheres, ao cuidado de Saasgaz eunuco do rei, vigilante das concubinas; ela não voltava mais ao rei, a não ser se o rei a desejasse, e fosse chamada por nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 15, 'Chegando, pois, a vez de Ester, filha de Abiail, tio de Mardoqueu (que e havia tinha tomado por filha), para vir ao rei, nenhuma coisa pediu a não ser o que Hegai eunuco do rei, vigilante das mulheres, havia dito; e Ester alcançava o favor aos olhos de todos quantos a viam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 16, 'Assim Ester foi levada ao rei Assuero a sua casa real no décimo mês, que é o mês de Tebete, no sétimo ano de seu reinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 17, 'E o rei amou a Ester mais que todas as mulheres, e alcançou diante dele favor e benevolência mais que todas as virgens; e ele pôs a coroa real em sua cabeça, e a fez rainha em lugar de Vasti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 18, 'Então o rei fez um grande banquete a todos seus príncipes e servos, o banquete de Ester; e deu repouso às províncias, e deu presentes, conforme a generosidade do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 19, 'E quando as virgens se ajuntaram pela segunda vez, Mardoqueu estava sentado à porta do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 20, 'Ester, [porém] ,não tinha declarado sua parentela nem seu povo, assim como Mardoqueu havia lhe mandado; porque Ester fazia o que Mardoqueu mandava, assim como quando ele a criava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 21, 'Naqueles dias, estando Mardoqueu sentado à porta do rei, Bigtã e Teres, dois eunucos do rei, dos guardas da porta, ficaram muito indignados, e procuravam matar o rei Assuero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 22, 'E isso foi percebido por Mardoqueu; então ele avisou à rainha Ester, e Ester disse ao rei em nome de Mardoqueu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 2, 23, 'Tendo o caso sido investigado, assim foi achado; e ambos foram pendurados em uma forca. E isso foi registrado nas crônicas diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 1, 'Depois destas coisas, o rei Assuero engrandeceu a Hamã filho de Hamedata agagita, e o exaltou, e pôs seu assento acima de todos os príncipes que estavam com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 2, 'E todos os servos do rei que estavam à porta do rei se inclinavam e prostravam diante de Hamã, porque assim o rei tinha mandado acerca dele; porém Mardoqueu não se inclinava nem se prostrava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 3, 'Então os servos do rei que estavam à porta do rei disseram a Mardoqueu: Por que transgrides o mandamento do rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 4, 'Sucedeu, pois, que, tendo eles dito [isto] dia após dia, e ele não tendo lhes dado ouvidos, avisaram dele a Hamã, para verem se as palavras de Mardoqueu continuariam; porque ele tinha lhes declarado que era judeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 5, 'Quando Hamã viu que Mardoqueu não se inclinava nem se prostrava diante dele, ele se encheu de furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 6, 'Porém, tendo já sido informado do povo de Mardoqueu, ele achou pouco matar apenas Mardoqueu; então Hamã procurou destruir a todos os judeus, o povo de Mardoqueu, que havia no reino de Assuero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 7, 'No primeiro mês (que é o mês de Nisã), no décimo segundo ano do rei Assuero, foi lançada Pur, isto é, a sorte, diante de Hamã, para cada dia e para cada mês; e [a sorte indicou] o décimo segundo mês, o mês de Adar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 8, 'Então Hamã disse ao rei Assuero: Há um povo disperso e dividido entre os povos em todas as províncias de teu reino, cujas leis são diferentes das de todo o povo, e não obedecem às leis do rei; por isso não convém ao rei tolerá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 9, 'Se for do agrado do rei, escreva-se que sejam destruídos; e eu porei dez mil talentos de prata nas mãos dos executarem a ação, para que sejam postos na tesouraria do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 10, 'Então o rei tirou seu anel de sua mão, e o deu a Hamã filho de Hamedata agageu, inimigo dos judeus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 11, 'E o rei disse a Hamã: Essa prata te seja dada; e também esse povo, para fazeres dele o que quiseres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 12, 'Então chamaram aos escrivães do rei no primeiro mês, no [dia] treze do mesmo, e foi escrito conforme a tudo o que Hamã mandou, aos príncipes do rei, e aos governadores que havia sobre cada província, e aos líderes de cada povo, a cada província conforme sua escrita, e a cada povo conforme sua língua; em nome do rei Assuero foi escrito, e com o anel do rei foi selado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 13, 'E foram enviadas cartas por meio de mensageiros a todas as províncias do rei, para destruírem, matarem, e exterminarem a todos os judeus, desde o menino até o velho, crianças e mulheres em um dia, no [dia] treze do décimo segundo mês (que é o mês de Adar), e para saquearem suas posses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 14, 'A cópia do texto foi entregue como decreto para que anunciasse em todas as províncias em público a todos os povos, para que estivessem preparados para aquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 3, 15, 'Assim os mensageiros, obrigados pela palavra do rei, saíram, e o decreto foi anunciado na fortaleza de Susã. E o rei e Hamã se sentaram para beber; porém a cidade de Susã estava confusa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 1, 'Quando Mardoqueu soube de tudo quanto havia acontecido, Mordecai rasgou suas vestes, e vestiu-se de saco e de cinza, e saiu andando por meio da cidade, clamando com grande e amargo clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 2, 'E chegou até diante da porta do rei, porque ninguém vestido de saco podia entrar pela porta do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 3, 'E em toda província e lugar onde a palavra do rei e seu decreto chegava, havia entre os judeus grande luto, jejum, choro, e lamentação; e muitos se deitaram em sacos e cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 4, 'Então as virgens de Ester e seus eunucos vieram e a informaram; então a rainha teve grande dor, e enviou roupas para vestir a Mardoqueu, e tirar o saco que estava sobre ele; porém ele não as aceitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 5, 'Então Ester chamou a Hatá, um dos eunucos do rei, que ele tinha posto para a servir, e o mandou a Mardoqueu, para saber o que era aquilo, e por quê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 6, 'Assim, pois Hatá veio a Mardoqueu à praça da cidade que estava diante da porta do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 7, 'E Mardoqueu lhe contou tudo o que tinha lhe acontecido, assim como a soma de prata que Hamã havia dito que daria para a tesouraria do rei por causa dos judeus, para os destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 8, 'Também lhe deu a cópia da escritura do decreto que tinha sido publicado em Susã para que fossem destruídos, a fim de a mostrar a Ester e a ela informar, e lhe mandar que fosse ao rei para lhe pedir e suplicar diante dele em favor de seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 9, 'Veio, pois, Hatá, e contou a Ester as palavras de Mardoqueu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 10, 'Então Ester respondeu a Hatá, e mandou-lhe [dizer] a Mardoqueu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 11, 'Todos os servos do rei e o povo das províncias do rei sabem que todo homem ou mulher que entra ao pátio interno na presença rei sem ser chamado, sua sentença é a morte, a não ser se o rei estender o cetro de ouro, para que viva; e eu nestes trinta dias não fui chamada para vir ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 12, 'E contaram a Mardoqueu as palavras de Ester.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 13, 'Então Mardoqueu disse que respondessem a Ester: Não penses em tua alma, que escaparás na casa do rei mais que todos os [outros] judeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 14, 'Porque se te calares agora, haverá alívio e libertação para os judeus de outra parte; porém tu e a casa de teu pai perecereis. E quem sabe se foi para tempo como este que chegaste a ser rainha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 15, 'Então Ester disse que respondessem a Mardoqueu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 16, 'Vai, e junta a todos os judeus que se acham em Susã, e jejuai por mim, e não comais nem bebais durante três dias, nem de noite nem de dia; eu e minhas virgens também assim jejuaremos; e assim virei ao rei, ainda que não seja segundo à lei; e se eu perecer, perecerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 4, 17, 'Então Mardoqueu se foi, e fez conforme tudo quanto Ester lhe mandara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 1, 'Aconteceu, pois, que ao terceiro dia Ester se vestiu de vestes reais, e se pôs no pátio de dentro da casa do rei, de frente ao aposento do rei; e o rei estava sentado em seu trono real no aposento real, em frente da porta do aposento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 2, 'E foi que, quando ele viu a rainha Ester, que estava no pátio, ela alcançou favor em seus olhos; e o rei apontou para Ester o cetro de ouro que tinha em sua mão. Então Ester se aproximou, e tocou a ponta do cetro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 3, 'Então o rei disse: O que tens, rainha Ester? E qual é a tua petição? Até a metade do reino será dada a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 4, 'E Ester respondeu: Se for do agrado do rei, venha o rei hoje com Hamã ao banquete que lhe tenho preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 5, 'Então o rei disse: Fazei Hamã se apressar a fazer o que Ester disse. Assim o rei veio com Hamã ao banquete que Ester havia preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 6, 'O rei perguntou a Ester no banquete do vinho: Qual é a tua petição, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 7, 'Então Ester respondeu, dizendo: Minha petição e minha demanda é:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 8, 'Se tenho achado favor aos olhos do rei, e se agrada ao rei conceder minha petição e fazer cumprir o meu pedido, que o rei venha com Hamã ao banquete que lhes prepararei; e amanhã farei conforme o que o rei tem dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 9, 'Então Hamã saiu naquele dia contente e alegre de coração; porém, quando viu a Mardoqueu à porta do rei, e que ele não se levantava nem se movia por ele, então Hamã se encheu de furor contra Mardoqueu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 10, 'Porém Hamã se conteve, e veio a sua casa, e mandou vir seus amigos, e a Zeres sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 11, 'E Hamã lhes contou a glória de seus riquezas, e a multidão de seus filhos, e tudo em que o rei tinha lhe engrandecido e lhe exaltado sobre os príncipes e servos do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 12, 'Hamã também disse: Até a rainha Ester a ninguém fez vir com o rei ao banquete que ela preparou, a não ser a mim; e ainda amanhã sou convidado dela juntamente com o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 13, 'Porém tudo isto não me satisfaz, enquanto eu ver o judeu Mardoqueu sentado à porta do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 5, 14, 'Então sua mulher Zeres e todos os seus amigos lhe disseram: Seja feita uma forca de cinquenta côvados de altura, e amanhã dize ao rei para que nela enforquem a Mardoqueu; e então vai alegre com o rei ao banquete. E este conselho foi do agrado de Hamã, e ele mandou fazer a forca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 1, 'Naquela noite o rei perdeu o sono. Então ele mandou trazer o livro das memórias das crônicas: e elas foram lidas na presença do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 2, 'E achou-se escrito que Mardoqueu havia denunciado Bigtã e de Teres, dois eunucos do rei, da guarda da porta, que tinham procurado matar o rei Assuero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 3, 'Então o rei disse: Que honra e que condecoração se fez a Mardoqueu por isto? E os servos do rei que o serviam disseram: Nada foi feito com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 4, 'Então o rei disse: Quem está no pátio? (Pois Hamã tinha vindo ao pátio de fora da casa do rei, para dizer ao rei que enforcassem a Mardoqueu na forca que tinha preparado para ele).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 5, 'E os servos do rei lhe responderam: Eis que Hamã está no pátio. E o rei mandou que ele entrasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 6, 'Quando Hamã entrou, o rei lhe perguntou: Que se fará ao homem a quem rei deseja honrar? Então Hamã pensou em seu coração: A quem o rei desejará mais dar honra que a mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 7, 'Por isso Hamã respondeu ao rei: Ao homem a quem o rei deseja honrar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 8, 'Tragam o vestido real de que o rei costuma se vestir, o cavalo em que o rei costuma cavalgar, e ponha-se a coroa real sobre sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 9, 'E entregue-se o vestido e o cavalo na mão de um dos mais importantes príncipes do rei, e vistam a tal homem a quem o rei deseja honrar, e levem-no a cavalo pelas ruas da cidade, e proclamem diante dele: Assim se fará ao homem a quem o rei deseja honrar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 10, 'Então o rei disse a Hamã: Apressa-te, toma o vestido e o cavalo, como disseste, e faze assim para com o judeu Mardoqueu, que se senta à porta do rei; não omitas coisa alguma de tudo quanto disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 11, 'E Hamã tomou o vestido e o cavalo, e vestiu a Mardoqueu; e o levou a cavalo pelas ruas da cidade, e proclamou diante dele: Assim se fará ao homem a quem o rei deseja honrar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 12, 'Depois disto Mardoqueu voltou à porta do rei. Porém Hamã se retirou correndo para sua casa, aborrecido, e com sua cabeça coberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 13, 'E Hamã contou a sua mulher Zeres e a todos seus amigos tudo o que tinha lhe acontecido; então seus sábios e sua mulher Zeres lhe disseram: Se Mardoqueu, diante de quem começaste a cair, é da semente dos judeus, tu não prevalecerás contra ele; ao contrário, certamente cairás diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 6, 14, 'Enquanto eles ainda estavam falando com ele, os eunucos do rei chegaram, apressados, para levarem Hamã ao banquete que Ester havia preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 1, 'Veio, pois, o rei com Hamã para beber com a rainha Ester.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 2, 'O rei disse também a Ester no segundo dia do banquete do vinho: Qual é tua petição, rainha Ester, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 3, 'Então a rainha Ester respondeu e disse: Ó rei, se tenho achado favor em teus olhos, e se for do agrado do rei, seja me dada minha vida por minha petição, e meu povo por meu pedido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 4, 'Porque estamos vendidos, eu e meu povo, para sermos destruídos, mortos e exterminados. Se [apenas] fôssemos ser vendidos como escravos e escravas, eu ficaria calada, pois tal opressão não compensaria incomodar ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 5, 'Então o rei Assuero respondeu à rainha Ester: Quem é esse, e onde está esse, que se atreveu a pensar em fazer assim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 6, 'E Ester disse: O homem opressor e inimigo é este malvado Hamã. Então Hamã se perturbou diante do rei e da rainha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 7, 'E o rei, em seu furor, se levantou do banquete do vinho, e [foi] ao jardim do palácio; e Hamã ficou em pé para suplicar à rainha Ester por sua vida; pois entendeu que o rei já havia decidido o mal contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 8, 'Quando o rei voltou do jardim do palácio ao lugar do banquete do vinho, Hamã estava caído sobre o leito em que Ester estava. Então disse o rei: Por acaso ele também queria abusar da rainha diante de mim nesta casa? Assim que esta palavra saiu da boca do rei, cobriram o rosto de Hamã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 9, 'Então Harbona, um dos eunucos que estavam na presença do rei, disse: Eis que há uma forca de cinquenta côvados de altura que Hamã fez para Mardoqueu, o qual falou para o bem do rei, junto à casa de Hamã. Então o rei disse: Enforcai-o nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 7, 10, 'Assim enforcaram a Hamã na forca que ele tinha mandado preparar para Mardoqueu; então o furor do rei se apaziguou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 1, 'Naquele mesmo dia o rei Assuero deu à rainha Ester a casa de Hamã, inimigo dos judeus; e Mardoqueu veio diante do rei, porque Ester [lhe] declarara o que ele era dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 2, 'E o rei tirou o seu anel que tinha tomado de Hamã, e o deu a Mardoqueu. E Ester pôs a Mardoqueu sobre [o comando] da casa de Hamã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 3, 'Ester falou novamente diante do rei, e lançou-se a seus pés, chorando e suplicando-lhe que revogasse a maldade de Hamã, agagita, e seu plano que tinha tramado contra os judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 4, 'Então o rei apontou para Ester o cetro de ouro; e Ester se levantou, e se pôs em pé diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 5, 'E disse: Se for do agrado do rei, e se tenho achado favor diante dele, e se for correto perante o rei, e se eu lhe agrado em seus olhos, escreva-se que sejam revogadas as cartas do plano de Hamã, filho de Hamedata, agagita, que ele escreveu para destruir os judeus que estão em todas as províncias do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 6, 'Pois como poderei eu ver o mal que sobrevirá a meu povo? Como poderei eu ver a destruição dos meus parentes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 7, 'Então o rei Assuero respondeu à rainha Ester e ao judeu Mardoqueu: Eis que dei a Ester a casa de Hamã, e a ele enforcaram na forca, por ter tentado matar os judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 8, 'Escrevei, pois, vós aos judeus como bem vos parecer em nome do rei, e selai o com o anel do rei; porque a escritura que é selada com o anel do rei, não pode ser revogada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 9, 'Então foram chamados os escrivães do rei naquele mesmo instante, no terceiro mês (que é Sivã), ao [dia] vinte e três do mesmo; e escreveu-se conforme tudo quanto Mardoqueu mandou, aos judeus, como também aos sátrapas, aos governadores, e aos líderes das províncias, que [se estendem] da Índia até Cuxe, cento e vinte e sete províncias, a cada província segundo sua escrita, e a cada povo conforme sua língua; como também aos judeus conforme sua escrita, e conforme sua língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 10, 'E escreveu-se em nome do rei Assuero, e selou-se com o anel do rei; e as cartas foram enviados por meio dos mensageiros por correios a cavalo, que cavalgavam sobre velozes cavalos, os quais pertenciam ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 11, 'Que o rei concedia aos judeus que havia em todas a cidades, que se ajuntassem e se pusessem em defesa de suas vidas, para destruírem, matarem e exterminarem todas as tropas de povo e província que viesse contra eles, até a crianças como a mulheres, e [os] despojassem de seus bens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 12, 'Em um mesmo dia, em todas as províncias do rei Assuero, no [dia] treze do décimo segundo mês, que é o mês de Adar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 13, 'A cópia da carta dada como decreto em todas as províncias foi anunciada publicamente a todos os povo, para que os judeus estivessem preparados para aquele dia, para se vingarem de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 14, 'Os mensageiros, sobre cavalos velozes, saíram apressadamente, impelidos pela ordem do rei; e o decreto também foi publicado na fortaleza de Susã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 15, 'Então Mardoqueu saiu de diante do rei com vestido real de azul celeste e branco, como também com uma grande coroa de ouro, e um manto de linho e púrpura; e a cidade de Susã jubilou e se alegrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 16, '[E] para os judeus houve luz, alegria, júbilo, e honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 8, 17, 'Também em cada província e em cada cidade aonde chegava a palavra do rei e seu decreto, havia entre os judeus alegria e júbilo, banquetes e dia de prazer. E muitos dos povos da terra se tornaram como judeus, porque o temor aos judeus havia caído sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 1, 'E no décimo segundo mês (que é o mês de Adar), no [dia] treze do mesmo, em que chegou o prazo para a palavra do rei se seu decreto serem executados, no mesmo dia em que os inimigos dos judeus esperavam vencê-los, sucedeu o contrário, porque foram os judeus que venceram aqueles que os odiavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 2, 'Os judeus se ajuntaram em suas cidades em todas as províncias do rei Assuero, para atacarem os que procuravam lhes fazer mal; e ninguém pôde subsistir diante deles, porque o temor a eles tinha caído sobre todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 3, 'E todos os governadores das províncias, e os sátrapas, e os líderes, e os oficiais do rei, auxiliavam os judeus; porque o temor a Mardoqueu tinha caído sobre eles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 4, 'Porque Mardoqueu era grande na casa do rei, e sua fama ia por todas as províncias; pois o homem Mardoqueu havia se engrandecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 5, 'Assim os judeus feriram a todos os seus inimigos com golpes de espada, matança, e destruição; e fizeram o que quiseram daqueles que os odiavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 6, 'E na fortaleza de Susã os judeus mataram e destruíram quinhentos homens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 7, 'Inclusive a Parsandata, Dalfom, Aspata,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 8, 'Porata, Adalia, Aridata,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 9, 'Farmasta, Arisai, Aridai, e a Vaisata,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 10, 'Os dez filhos de Hamã filho de Hamedata, inimigo dos judeus; porém não puseram suas mãos no despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 11, 'No mesmo dia veio diante do rei a contagem dos mortos na fortaleza de Susã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 12, 'E o rei disse à rainha Ester: Na fortaleza de Susã, os judeus mataram e destruíram a quinhentos homens, e aos dez filhos de Hamã; nas demais províncias do rei, o que teriam feito? Qual pois é tua petição, para que te seja concedida? Ou qual mais é teu pedido, para que te seja feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 13, 'Então Ester disse: Se for do agrado do rei, conceda-se também amanhã aos judeus em Susã, que façam conforme a lei de hoje; e que enforquem na forca os dez filhos de Hamã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 14, 'Então o rei disse que assim se fizesse; e deu-se a ordem em Susã, e enforcaram aos dez filhos de Hamã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 15, 'E os judeus que estavam em Susã se ajuntaram também no [dia] catorze do mês de Adar, e mataram trezentos homens em Susã; porém não puseram suas mãos no despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 16, 'Também os demais judeus que estavam nas províncias do rei se ajuntaram e para se porem em defesa de sua vida, e terem repouso de seus inimigos; e mataram a setenta e cinco mil daqueles que os odiavam; porém não puseram suas mãos no despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 17, '[Sucedeu isto] no [dia] treze do mês de Adar; e repousaram no [dia] catorze do mesmo, e fizeram dele um dia de banquetes e de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 18, 'Também os judeus que estavam em Susã se ajuntaram nos [dias] treze e catorze do mesmo mês; e no [dia] quinze do mesmo repousaram, e fizeram daquele dia um dia de banquetes e de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 19, 'Por isso os judeus das aldeias, que habitavam nas cidades se muros, fizeram o [dia] catorze do mês de Adar um dia de alegria, de banquetes, e dia de festejo; e de mandarem presentes uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 20, 'E Mardoqueu escreveu estas coisas, e enviou cartas a todos os judeus que havia em todas as províncias do rei Assuero, próximos e distantes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 21, 'Ordenando-lhes que comemorassem o décimo quarto [dia] do mês de Adar, e o décimo quinto do mesmo, todos os anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 22, 'Como os dias em que os judeus tiveram repouso de seus inimigos; e o mês que tornou para eles de tristeza em alegria, e de luto em dia de festejo; para que os fizessem dias de banquetes e de alegria, e de mandarem presentes uns aos outros, e de doações aos pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 23, 'E os judeus aceitaram fazer o que já tinham começado assim como o que Mardoqueu havia lhes escrito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 24, 'Porque Hamã filho de Hamedata, o agagita, inimigo de todos os judeus, tinha planejado destruir todos os judeus, e lançou Pur, isto é, sorte, para os oprimir e os destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 25, 'Mas quando isto veio diante do rei, ele deu ordem por cartas, que seu plano maligno, que tramara contra os judeus, tornasse sobre sua cabeça; assim enforcaram a ele e a seus filhos na forca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 26, 'Por isso aqueles dias foram chamados Purim, por causa do nome Pur. Portanto, por causa de todas as palavras daquela carta; e do que testemunharam quanto a isso, e do que veio sobre eles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 27, 'Os judeus confirmaram e comprometeram a si mesmos e a seus descendentes, e a todos os que se fossem próximos deles, que não deixariam de comemorar estes dois dias conforme o que foi escrito deles, e conforme seu tempo determinado, todos os anos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 28, 'E que estes dias seriam lembrados e comemorados em todas as gerações, famílias, províncias, e cidades; e que estes dias de Purim não seriam ignorados pelos judeus, e que sua lembrança nunca teria fim entre seus descendentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 29, 'Depois disto a rainha Ester, filha de Abiail, e o judeu Mardoqueu, escreveram com todo poder, para confirmarem pela segunda vez esta carta de Purim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 30, 'E foram enviadas cartas a todos os judeus, às cento e vinte e sete províncias do rei Assuero, com palavras de paz e de verdade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 31, 'Para confirmarem estes dias de Purim em seus tempos determinados, conforme o judeu Mardoqueu e a rainha Ester tinham lhes confirmado, e como eles mesmos já o confirmaram para si e para seus descendentes; acerca do jejum e de seu clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 9, 32, 'E o mandamento de Ester confirmou estas palavras dadas acerca de Purim, e escreveu-se em um livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 10, 1, 'E o rei Assuero impôs um tributo sobre a terra e [sobre] as ilhas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 10, 2, 'E todas as obras de seu poder e de seu valor, e a declaração da grandeza de Mardoqueu, a quem o rei engrandeceu, por acaso não estão escritas no livro das crônicas dos reis da Média e da Pérsia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 17, 'Ester', 'Et', 10, 3, 'Pois o judeu Mardoqueu foi o segundo depois do rei Assuero, e grande entre os judeus, e agradável à multidão de seus irmãos, procurando o bem de seu povo, e falando prosperidade para todo o seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 1, 'Havia um homem na terra de Uz, cujo nome era Jó; e este homem era íntegro e correto, temente a Deus, e que se afastava do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 2, 'E nasceram-lhe sete filhos e três filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 3, 'E seu patrimônio era sete mil ovelhas, três mil camelos, quinhentas juntas de bois, e quinhentas jumentas; ele também tinha muitíssimos servos, de maneira que este homem era o maior de todos do oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 4, 'E seus filhos iam nas casas uns dos outros para fazerem banquetes, cada um em seu dia; e mandavam convidar as suas três irmãs, para que comessem e bebessem com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 5, 'E acontecia que, acabando-se o revezamento dos dias de banquetes, Jó enviava e os santificava, e se levantava de madrugada para apresentar holocaustos[conforme] o número de todos eles. Pois Jó dizia: Talvez meus filhos tenham pecado, e tenham amaldiçoado a Deus em seus corações. Assim Jó fazia todos aqueles dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 6, 'E em certo dia, os filhos de Deus vieram para se apresentarem diante do SENHOR, e Satanás também veio entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 7, 'Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, dizendo: De rodear a terra, e de passear por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 8, 'E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há na terra semelhante a ele, homem íntegro e correto, temente a Deus, e que se afasta de mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 9, 'Então Satanás respondeu ao SENHOR, dizendo: Por acaso Jó teme a Deus em troca de nada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 10, 'Por acaso tu não puseste uma cerca ao redor dele, de sua casa, e de tudo quanto ele tem? Tu abençoaste o trabalho de suas mãos, e seu patrimônio tem crescido sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 11, 'Mas estende agora tua mão, e toca em tudo quanto ele tem; e [verás] se ele não te amaldiçoa em tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 12, 'E o SENHOR disse a Satanás: Eis que tudo quanto ele tem está em tua mão; somente não estendas tua mão contra ele. E Satanás saiu de diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 13, 'E sucedeu um dia que seus filhos e filhas estavam comendo e bebendo vinho na casa de seu irmão primogênito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 14, 'Que veio um mensageiro a Jó, que disse: Enquanto os bois estavam arando, e as jumentas se alimentando perto deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 15, 'Eis que os sabeus atacaram, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 16, 'Enquanto este ainda estava falando, veio outro que disse: Fogo de Deus caiu do céu, que incendiou as ovelhas entre os servos, e os consumiu; somente eu escapei para te trazer-te a notícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 17, 'Enquanto este ainda estava falando, veio outro que disse: Os caldeus formaram três tropas, e atacaram os camelos, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 18, 'Enquanto este ainda estava falando, veio outro que disse: Teus filhos e tuas filhas estavam comendo e bebendo vinho em casa de seu irmão primogênito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 19, 'E eis que veio um grande vento do deserto, e atingiu os quatro cantos da casa, que caiu sobre os jovens, e morreram; somente eu escapei para te trazer a notícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 20, 'Então Jó se levantou, rasgou sua capa, rapou sua cabeça, e caindo na terra, adorou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 21, 'E disse: Nu saí do ventre de minha mãe, e nu para lá voltarei. O SENHOR deu, e o SENHOR tomou; bendito seja o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 1, 22, 'Em tudo isto Jó não pecou, nem atribuiu a Deus falta alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 1, 'E veio outro dia em que os filhos de Deus vieram para se apresentarem diante do SENHOR, e e Satanás também veio entre eles para se apresentar diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 2, 'Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, e dizendo: De rodear a terra, e de passear por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 3, 'E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há semelhante a ele na terra, homem íntegro e correto, temente a Deus e que se afasta do mal; e que ainda mantém sua integridade, mesmo depois de teres me incitado contra ele, para o arruinar sem causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 4, 'Então Satanás respondeu ao SENHOR, dizendo: Pele por pele, e tudo quanto o homem tem, dará por sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 5, 'Mas estende agora tua mão, e toca em seus ossos e sua carne, e [verás] se ele não te amaldiçoa em tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 6, 'E o SENHOR disse a Satanás: Eis que ele está em tua mão; mas preserva sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 7, 'Então Satanás saiu de diante do SENHOR, e feriu a Jó de chagas malignas desde a planta de seus pés até a topo de sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 8, 'E [Jó] tomou um caco para se raspar com ele, e ficou sentado no meio da cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 9, 'Então sua mulher lhe disse: Ainda manténs a tua integridade? Amaldiçoa a Deus, e morre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 10, 'Porém ele lhe disse: Tu falas como uma tola. Receberíamos o bem de Deus, e o mal não receberíamos? Em tudo isto Jó não pecou com seus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 11, 'Quando três amigos de Jó, Elifaz temanita, Bildade suíta, e Zofar naamita, ouviram todo este mal que lhe tinha vindo sobre ele, vieram cada um de seu lugar; porque haviam combinado de juntamente virem para se condoerem dele, e o consolarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 12, 'Eles, quando levantaram seus olhos de longe, não o reconheceram; e choraram em alta voz; e cada um deles rasgou sua capa, e espalharam pó ao ar sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 2, 13, 'Assim se sentaram com ele na terra durante sete dias e sete noites, e nenhum lhe falava palavra alguma, pois viam que a dor era muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 1, 'Depois disto Jó abriu sua boca, e amaldiçoou seu dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 2, 'Pois Jó respondeu, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 3, 'Pereça o dia em que nasci, e a noite [em que] se disse: Um homem foi concebido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 4, 'Torne-se aquele dia em trevas; Deus não lhe dê atenção desde acima, nem claridade brilhe sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 5, 'Reivindiquem-no para si trevas e sombra de morte; nuvens habitem sobre ele; a escuridão do dia o espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 6, 'Tome a escuridão aquela noite; não seja contada entre os dias do ano, nem faça parte do número dos meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 7, 'Ah se aquela noite fosse solitária, e música de alegria não viesse a ela!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 8, 'Amaldiçoem-na os que amaldiçoam o dia, os que se preparam para levantar seu pranto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 9, 'Escureçam-se as estrelas de sua manhã; espere a luz, e não venha, e as pálpebras não vejam o amanhecer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 10, 'Pois não fechou as portas do ventre onde eu estava, nem escondeu de meus olhos o sofrimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 11, 'Por que eu não morri desde a madre, ou perdi a vida ao sair do ventre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 12, 'Por que joelhos me receberam? E por que seios me amamentaram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 13, 'Pois agora eu jazeria e repousaria; dormiria, e então haveria repouso para mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 14, 'Com os reis e os conselheiros da terra, que edificavam para si os desertos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 15, 'Ou com os príncipes que tinham ouro, que enchiam suas casas de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 16, 'Ou [por que] não fui como um aborto oculto, como as crianças que nunca viram a luz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 17, 'Ali os maus deixam de perturbar, e ali repousam os cansados de forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 18, 'Ali os prisioneiros juntamente repousam; [e] não ouvem a voz do opressor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 19, 'Ali estão o pequeno e o grande; e o servo livre [está] de seu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 20, 'Por que se dá luz ao sofredor, e vida aos amargos de alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 21, 'Que esperam a morte, e ela não chega, e que a buscam mais que tesouros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 22, 'Que saltam de alegram e ficam contentes quando acham a sepultura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 23, '[E também] ao homem cujo caminho é oculto, e a quem Deus [o] encobriu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 24, 'Pois antes do meu pão vem meu suspiro; e meus gemidos correm como águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 25, 'Pois aquilo eu temia tanto veio a mim, e aquilo que tinha medo me aconteceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 3, 26, 'Não tenho tido descanso, nem tranquilidade, nem repouso; mas perturbação veio sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 1, 'Então Elifaz o temanita respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 2, 'Se tentarmos falar contigo, ficarás incomodado? Mas quem poderia deter as palavras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 3, 'Eis que tu ensinavas a muitos, e fortalecias as mãos fracas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 4, 'Tuas palavras levantavam aos que tropeçavam, e fortificavas os joelhos que desfaleciam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 5, 'Mas agora [isso] que aconteceu contigo, tu te cansas; e quando [isso] te tocou, te perturbas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 6, 'Por acaso não era o teu temor [a Deus] a tua confiança, e a integridade dos teus caminhos tua esperança?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 7, 'Lembra-te agora, qual foi o inocente que pereceu? E onde os corretos foram destruídos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 8, 'Como eu tenho visto, os que lavram injustiça e semeiam opressão colhem o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 9, 'Com o sopro de Deus eles perecem, e pelo vento de sua ira são consumidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 10, 'O rugido do leão, a voz do leão feroz, e os dentes dos leões jovens são quebrantados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 11, 'O leão velho perece por falta de presa, e os filhotes da leoa se dispersam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 12, 'Uma palavra me foi dita em segredo, e meu ouvidos escutaram um sussurro dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 13, 'Em imaginações de visões noturnas, quando o sono profundo cai sobre os homens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 14, 'Espanto e tremor vieram sobre mim, que espantou todos os meus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 15, 'Então um vento passou por diante de mim, que fez arrepiar os pelos de minha carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 16, 'Ele parou, mas não reconheci sua feição; uma figura estava diante de meus olhos, e ouvi uma voz quieta, [que dizia] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 17, 'Seria o ser humano mais justo que Deus? Seria o homem mais puro que seu Criador?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 18, 'Visto que ele não confia em seus servos, e considera seus anjos como loucos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 19, 'Quanto mais naqueles que habitam em casas de lodo, cujo fundamento está no pó, e são esmagáveis como a traça!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 20, 'Desde a manhã até a tarde são despedaçados, e perecem sempre, sem que ninguém perceba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 4, 21, 'Por acaso sua excelência não se perde com eles mesmos? Eles morrem sem sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 1, 'Clama agora! Haverá alguém que te responda? E a qual dos santos te voltarás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 2, 'Pois a ira acaba com o louco, e o zelo mata o tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 3, 'Eu vi ao louco lançar raízes, porém logo amaldiçoei sua habitação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 4, 'Seus filhos estarão longe da salvação; na porta são despedaçados, e não há quem os livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 5, 'O faminto devora sua colheita, e a tira até dentre os espinhos; e o assaltante traga sua riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 6, 'Porque a aflição não procede do pó da terra, nem a opressão brota do chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 7, 'Mas o ser humano nasce para a opressão, assim como as faíscas das brasas se levantam a voar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 8, 'Porém eu buscaria a Deus, e a ele confiaria minha causa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 9, '[Pois] ele é o que faz coisas grandiosas e incompreensíveis, e inúmeras maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 10, 'Ele é o que dá a chuva sobre a face da terra, e envia águas sobre os campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 11, 'Ele põe os humildes em lugares altos, para que os sofredores sejam postos em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 12, 'Ele frustra os planos dos astutos, para que suas mãos nada consigam executar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 13, 'Ele prende aos sábios em sua própria astúcia; para que o conselho dos perversos seja derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 14, 'De dia eles se encontram com as trevas, e ao meio-dia andam apalpando como de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 15, 'Porém livra ao necessitado da espada de suas bocas, e da mão do violento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 16, 'Pois ele é esperança para o necessitado, e a injustiça tapa sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 17, 'Eis que bem-aventurado é o homem a quem Deus corrige; portanto não rejeites o castigo do Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 18, 'Pois ele faz a chaga, mas também põe o curativo; ele fere, mas suas mãos curam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 19, 'Em seis angústias ele te livrará, e em sete o mal não te tocará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 20, 'Na fome ele te livrará da morte, e na guerra [livrará] do poder da espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 21, 'Do açoite da língua estarás encoberto; e não temerás a destruição quando ela vier.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 22, 'Tu rirás da destruição e da fome, e não temerás os animais da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 23, 'Pois até com as pedras do campo terás teu pacto, e os animais do campo serão pacíficos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 24, 'E saberás que há paz em tua tenda; e visitarás tua habitação, e não falharás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 25, 'Também saberás que tua semente se multiplicará, e teus descendentes serão como a erva da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 26, 'Na velhice virás à sepultura, como o amontoado de trigo que se recolhe a seu tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 5, 27, 'Eis que é isto o que temos constatado, e assim é; ouve-o, e pensa nisso tu para teu [bem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 1, 'Mas Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 2, 'Oh se pesassem justamente minha aflição, e meu tormento juntamente fosse posto em uma balança!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 3, 'Pois na verdade seria mais pesada que a areia dos mares; por isso minhas palavras têm sido impulsivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 4, 'Porque as flechas do Todo-Poderoso estão em mim, cujo veneno meu espírito bebe; e temores de Deus me atacam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 5, 'Por acaso o asno selvagem zurra junto à erva, ou o boi berra junto a seu pasto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 6, 'Por acaso se come o insípido sem sal? Ou há gosto na clara do ovo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 7, 'Minha alma se recusa tocar [essas coisas] ,que são para mim como comida detestável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 8, 'Ah se meu pedido fosse realizado, e se Deus [me] desse o que espero!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 9, 'Que Deus me destruísse; ele soltasse sua mão, e acabasse comigo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 10, 'Isto ainda seria meu consolo, um alívio em meio ao tormento que não [me] poupa; pois eu não tenho escondido as palavras do Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 11, 'Qual é minha força para que eu espere? E qual meu fim, para que eu prolongue minha vida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 12, 'É, por acaso, a minha força a força de pedras? Minha carne é de bronze?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 13, 'Tenho eu como ajudar a mim mesmo, se todo auxílio me foi tirado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 14, 'Ao aflito, seus amigos deviam ser misericordiosos, mesmo se ele tivesse abandonado o temor ao Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 15, 'Meus irmãos foram traiçoeiros comigo, como ribeiro, como correntes de águas que transbordam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 16, 'Que estão escurecidas pelo gelo, e nelas se esconde a neve;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 17, 'Que no tempo do calor se secam e, ao se aquecerem, desaparecem de seu lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 18, 'Os cursos de seus caminhos se desviam; vão se minguando, e perecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 19, 'As caravanas de Temã as veem; os viajantes de Sabá esperam por elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 20, 'Foram envergonhados por aquilo em que confiavam; e ao chegarem ali, ficaram desapontados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 21, 'Agora, vós vos tornastes semelhantes a elas; pois vistes o terror, e temestes.')
